package br.com.bemdoar.controller;
import br.com.bemdoar.dto.*;import br.com.bemdoar.security.UsuarioAutenticado;import br.com.bemdoar.service.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/notificacoes")public class NotificacaoController{private final NotificacaoService s;public NotificacaoController(NotificacaoService s){this.s=s;}private Long uid(Authentication a){return ((UsuarioAutenticado)a.getPrincipal()).getId();}@GetMapping("/minhas")public List<NotificacaoResponse> minhas(Authentication a){return s.listarMinhas(uid(a));}@PatchMapping("/{id}/lida")public NotificacaoResponse lida(@PathVariable Long id,Authentication a){return s.marcarComoLida(id,uid(a));}}
